 async void Export_Click(object s,RoutedEventArgs e){
  PersistEditor();
  var dlg=new Window{Title="내보내기",Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Width=430,Height=175,ResizeMode=ResizeMode.NoResize,Background=(Brush)FindResource("Panel"),Foreground=(Brush)FindResource("Text")};
  var root=new StackPanel{Margin=new Thickness(20)};root.Children.Add(new TextBlock{Text="내보내기",FontSize=17,FontWeight=FontWeights.SemiBold,Margin=new Thickness(2,0,0,14)});
  var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition());
  string? format=null;
  Button Make(string text,string key,int col){var b=new Button{Content=text,Height=54,Margin=new Thickness(col==0?0:5,0,col==2?0:5,0),FontSize=14,FontWeight=FontWeights.SemiBold};Grid.SetColumn(b,col);b.Click+=(_,_)=>{format=key;dlg.DialogResult=true;};row.Children.Add(b);return b;}
  Make("HWPX","hwpx",0);Make("DOCX","docx",1);Make("PDF","pdf",2);root.Children.Add(row);dlg.Content=root;dlg.SourceInitialized+=(_,_)=>ApplyWindowChromeTheme(dlg);
  if(dlg.ShowDialog()!=true||format==null)return;
  var ext=format=="hwpx"?".hwpx":format=="docx"?".docx":".pdf";
  var label=format.ToUpperInvariant();
  var filter=format=="hwpx"?"한글 HWPX (*.hwpx)|*.hwpx":format=="docx"?"Word DOCX (*.docx)|*.docx":"PDF (*.pdf)|*.pdf";
  var baseName=Regex.Replace(string.IsNullOrWhiteSpace(_document.Project.Title)?"novel":_document.Project.Title,@"[\\/:*?""<>|]","_");
  var save=new SaveFileDialog{Filter=filter,DefaultExt=ext,AddExtension=true,FileName=baseName+ext};
  if(save.ShowDialog()!=true)return;
  try{
   if(format=="hwpx")await DocumentExportService.ExportHwpxAsync(save.FileName,_document);
   else if(format=="docx")await DocumentExportService.ExportDocxAsync(save.FileName,_document);
   else DocumentExportService.ExportPdf(save.FileName,CreateNormalFlowDocument());
   UpdateStatus($"{label} 내보내기 완료");
  }catch(Exception ex){MessageBox.Show(ex.Message,"내보내기 실패");}
 }
