 void BuildNormalPreview(Panel host){var page=CreatePrintPage(PrintMode.Normal);var body=new StackPanel();page.Child=body;var title=new TextBlock{Text=_document.Project.Title,FontFamily=Editor.FontFamily,FontSize=24,FontWeight=FontWeights.SemiBold,Foreground=Brushes.Black,TextAlignment=TextAlignment.Center,HorizontalAlignment=HorizontalAlignment.Stretch,Margin=new Thickness(0,0,0,34)};body.Children.Add(title);var chapters=_document.Chapters.OrderBy(x=>x.Order).ToList();for(int i=0;i<chapters.Count;i++){var ch=chapters[i];body.Children.Add(new TextBlock{Text=ch.Title,FontFamily=Editor.FontFamily,FontSize=18,FontWeight=FontWeights.SemiBold,Foreground=Brushes.Black,Margin=new Thickness(0,12,0,18)});foreach(var sc in ch.Scenes.OrderBy(x=>x.Order))if(!string.IsNullOrWhiteSpace(sc.Content))body.Children.Add(new TextBlock{Text=sc.Content,FontFamily=Editor.FontFamily,FontSize=17,Foreground=Brushes.Black,TextWrapping=TextWrapping.Wrap,LineHeight=Math.Max(Editor.FontSize*1.7,Editor.FontSize+6),Margin=new Thickness(0,0,0,8)});if(i<chapters.Count-1)body.Children.Add(new Border{Height=1,Background=Brushes.LightGray,Margin=new Thickness(0,30,0,30)});}host.Children.Add(page);}
