 FlowDocument CreateNormalFlowDocument(){var doc=new FlowDocument{FontFamily=Editor.FontFamily,FontSize=Editor.FontSize,PagePadding=new Thickness(55),Foreground=Brushes.Black,Background=Brushes.White};doc.Blocks.Add(new Paragraph(new Run(_document.Project.Title)){TextAlignment=TextAlignment.Center,FontSize=Editor.FontSize+5,FontWeight=FontWeights.SemiBold,Foreground=Brushes.Black,Background=Brushes.White,Margin=new Thickness(0,0,0,34)});var chapters=_document.Chapters.OrderBy(x=>x.Order).ToList();for(int i=0;i<chapters.Count;i++){var ch=chapters[i];doc.Blocks.Add(new Paragraph(new Run(ch.Title)){FontSize=Editor.FontSize+1,FontWeight=FontWeights.SemiBold,Foreground=Brushes.Black,Margin=new Thickness(0,24,0,12)});foreach(var sc in ch.Scenes.OrderBy(x=>x.Order))if(!string.IsNullOrWhiteSpace(sc.Content))doc.Blocks.Add(new Paragraph(new Run(sc.Content)){Foreground=Brushes.Black,LineHeight=Math.Max(Editor.FontSize*1.7,Editor.FontSize+6),Margin=new Thickness(0,0,0,8)});if(i<chapters.Count-1)doc.Blocks.Add(new BlockUIContainer(new Border{Height=1,Background=Brushes.LightGray,Margin=new Thickness(0,20,0,20)}));}return doc;}
