 void EnsureTypingSoundsLoaded(){if(_typingSoundsLoaded)return;var root=System.IO.Path.Combine(AppContext.BaseDirectory,"Assets","Sounds");var typewriterKey=PrepareTypewriterKeySample(root);var typewriterEnter=PrepareTypewriterEnterSample(root);LoadTypingSample("typewriter",typewriterKey,4);for(int i=1;i<=2;i++)LoadTypingSample($"keyboard{i}",System.IO.Path.Combine(root,"Keyboard",$"key-{i:00}.wav"),i);LoadTypingSample("typewriter-space",System.IO.Path.Combine(root,"Typewriter","space.wav"),4);LoadTypewriterEnterSample(typewriterEnter);_typingSoundsLoaded=_typingSoundPlayers.Count>0||_typewriterEnterPlayer!=null;ApplyTypingVolume();}
 string PrepareTypewriterKeySample(string root){var encodedPath=System.IO.Path.Combine(root,"Typewriter","key.b64");try{if(!System.IO.File.Exists(encodedPath))return "";var encoded=System.IO.File.ReadAllText(encodedPath).Trim();var bytes=Convert.FromBase64String(encoded);if(bytes.Length<44||Encoding.ASCII.GetString(bytes,0,4)!="RIFF")return "";var cacheDir=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TagWriter","Sounds");System.IO.Directory.CreateDirectory(cacheDir);var path=System.IO.Path.Combine(cacheDir,"typewriter-key-2842-v1.wav");if(!System.IO.File.Exists(path)||new System.IO.FileInfo(path).Length!=bytes.Length)System.IO.File.WriteAllBytes(path,bytes);return path;}catch{return "";}}
