 void PlayTypingKey(KeyEventArgs e){if(!_appSettings.TypingSoundEnabled||_scene==null)return;if((Keyboard.Modifiers&(ModifierKeys.Control|ModifierKeys.Alt|ModifierKeys.Windows))!=0)return;var key=e.Key==Key.ImeProcessed?e.ImeProcessedKey:e.Key;if(key==Key.Return&&!string.Equals(_appSettings.TypingSoundMode,"keyboard",StringComparison.OrdinalIgnoreCase)){if(!e.IsRepeat)PlayTypewriterEnterSample();return;}var id=TypingSampleForKey(key);if(id!=null)PlayTypingSample(id);}
 string? TypingSampleForKey(Key key){var group=TypingKeyGroup(key);if(group==0)return null;if(string.Equals(_appSettings.TypingSoundMode,"keyboard",StringComparison.OrdinalIgnoreCase))return $"keyboard{group}";if(key==Key.Space)return "typewriter-space";return "typewriter";}
 int TypingKeyGroup(Key key)=>key switch{Key.Space=>1,Key.Back or Key.Delete or Key.Return=>2,Key.Tab=>1,Key.Q or Key.W or Key.E or Key.R or Key.T or Key.A or Key.S or Key.D or Key.F or Key.G or Key.Z or Key.X or Key.C or Key.V or Key.B or Key.D1 or Key.D2 or Key.D3 or Key.D4 or Key.D5=>1,Key.Y or Key.U or Key.I or Key.O or Key.P or Key.H or Key.J or Key.K or Key.L or Key.N or Key.M or Key.D6 or Key.D7 or Key.D8 or Key.D9 or Key.D0 or Key.OemComma or Key.OemPeriod or Key.OemSemicolon or Key.OemQuotes or Key.OemQuestion or Key.OemOpenBrackets or Key.OemCloseBrackets or Key.OemPipe or Key.OemPlus or Key.OemMinus or Key.OemTilde=>2,Key.NumPad0 or Key.NumPad1 or Key.NumPad2 or Key.NumPad3 or Key.NumPad4 or Key.NumPad5 or Key.NumPad6 or Key.NumPad7 or Key.NumPad8 or Key.NumPad9 or Key.Decimal or Key.Add or Key.Subtract or Key.Multiply or Key.Divide=>2,_=>0};
 void PlayTypewriterEnterSample(){EnsureTypingSoundsLoaded();if(_typewriterEnterPlaying||_typewriterEnterPlayer==null)return;_typewriterEnterPlaying=true;_typewriterEnterPlayer.Position=TimeSpan.Zero;_typewriterEnterPlayer.Play();}
 void PlayTypingSample(string id){EnsureTypingSoundsLoaded();if(!_typingSoundPlayers.TryGetValue(id,out var players)||players.Length==0)return;var cursor=_typingSoundPlayerCursor.TryGetValue(id,out var n)?n:0;var player=players[cursor%players.Length];_typingSoundPlayerCursor[id]=(cursor+1)%players.Length;player.Position=TimeSpan.Zero;player.Play();}
 void InitializeEditorPreferences(){var preferred=new[]{"Malgun Gothic","Batang","Noto Sans KR","Noto Serif KR","Segoe UI","Arial","Times New Roman","Georgia"};var installed=Fonts.SystemFontFamilies.ToDictionary(f=>f.Source,StringComparer.OrdinalIgnoreCase);var fonts=preferred.Where(installed.ContainsKey).Select(n=>installed[n]).ToList();if(!fonts.Any(f=>f.Source.Equals(_appSettings.EditorFontFamily,StringComparison.OrdinalIgnoreCase))){try{fonts.Insert(0,new FontFamily(_appSettings.EditorFontFamily));}catch{}}FontFamilyBox.ItemsSource=fonts;FontFamilyBox.SelectedItem=fonts.FirstOrDefault(f=>f.Source.Equals(_appSettings.EditorFontFamily,StringComparison.OrdinalIgnoreCase))??fonts.FirstOrDefault();FontSizeBox.ItemsSource=new double[]{10,11,12,13,14,15,16,17,18,20,22,24,26,28,32};FontSizeBox.SelectedItem=FontSizeBox.Items.Cast<double>().OrderBy(v=>Math.Abs(v-_appSettings.EditorFontSize)).First();ApplyEditorPreferences();}
 void ApplyEditorPreferences(){try{Editor.FontFamily=new FontFamily(_appSettings.EditorFontFamily);FullManuscriptReader.FontFamily=new FontFamily(_appSettings.EditorFontFamily);}catch{Editor.FontFamily=new FontFamily("Malgun Gothic");FullManuscriptReader.FontFamily=new FontFamily("Malgun Gothic");}Editor.FontSize=Math.Clamp(_appSettings.EditorFontSize,9,48);FullManuscriptReader.FontSize=Editor.FontSize;Editor.Document.FontFamily=Editor.FontFamily;Editor.Document.FontSize=Editor.FontSize;Editor.Document.PagePadding=new Thickness(0);Editor.Document.SetValue(Block.LineHeightProperty,Math.Max(Editor.FontSize*1.7,Editor.FontSize+6));ApplyEditorPaperStyle();ScheduleTagFormatting();}
 void InitializeEditorPaperPreferences(){
  var allowed=new[]{"lined","dots","dashed","blank"};if(!allowed.Contains(_appSettings.EditorPaperStyle))_appSettings.EditorPaperStyle="blank";
  if(EditorPaperStyleComboBox!=null){foreach(var item in EditorPaperStyleComboBox.Items.OfType<ComboBoxItem>())if(string.Equals(item.Tag?.ToString(),_appSettings.EditorPaperStyle,StringComparison.OrdinalIgnoreCase)){EditorPaperStyleComboBox.SelectedItem=item;break;}}
  ApplyEditorPaperStyle();
 }
 void EditorPaperStyleComboBox_SelectionChanged(object s,SelectionChangedEventArgs e){
  if(EditorPaperStyleComboBox.SelectedItem is not ComboBoxItem item)return;var style=item.Tag?.ToString()??"blank";_appSettings.EditorPaperStyle=style;ApplyEditorPaperStyle();if(IsLoaded)AppSettingsStore.Save(_appSettings);
 }
 void UpdateEditorPaperBackgroundVisibility(){
  if(EditorPaperBackground==null)return;
  EditorPaperBackground.Visibility=_scene!=null&&!_paperMode&&Editor.Visibility==Visibility.Visible&&FullManuscriptReader.Visibility!=Visibility.Visible
   ?Visibility.Visible:Visibility.Collapsed;
 }
 void ApplyEditorPaperStyle(){
  if(EditorPaperBackground==null)return;
  UpdateEditorPaperBackgroundVisibility();
  var style=_appSettings.EditorPaperStyle??"blank";if(style=="blank"){EditorPaperBackground.Background=null;return;}
  var lineColor=_dark?Color.FromArgb(82,92,105,121):Color.FromArgb(76,142,153,168);
  var dotColor=_dark?Color.FromArgb(100,112,126,144):Color.FromArgb(92,130,143,160);
  double spacing=Math.Max(24,Math.Round(_appSettings.EditorFontSize*1.7));
  double tile=style=="dots"?24:spacing;
  var group=new DrawingGroup();
  if(style=="dots"){
   group.Children.Add(new GeometryDrawing(new SolidColorBrush(dotColor),null,new EllipseGeometry(new Point(tile/2,tile/2),1.15,1.15)));
  }else{
   var pen=new Pen(new SolidColorBrush(lineColor),1);
   if(style=="dashed")pen.DashStyle=new DashStyle(new double[]{3,4},0);
   // Keep the notebook rule just beneath the text/tag underline.
   // The tag underline is rendered above this background layer, so near-overlap is intentional.
   var baselineLift=Math.Max(13,Math.Min(18,_appSettings.EditorFontSize*0.95));
   var lineY=Math.Max(1,tile-baselineLift);
   group.Children.Add(new GeometryDrawing(null,pen,new LineGeometry(new Point(0,lineY),new Point(tile,lineY))));
  }
  EditorPaperBackground.Background=new DrawingBrush(group){TileMode=TileMode.Tile,ViewportUnits=BrushMappingMode.Absolute,Viewport=new Rect(0,0,tile,tile),ViewboxUnits=BrushMappingMode.Absolute,Viewbox=new Rect(0,0,tile,tile),Stretch=Stretch.None};
 }
 void FontFamilyBox_SelectionChanged(object s,SelectionChangedEventArgs e){if(FontFamilyBox.SelectedItem is FontFamily f){_appSettings.EditorFontFamily=f.Source;ApplyEditorPreferences();}}
 void FontSizeBox_SelectionChanged(object s,SelectionChangedEventArgs e){if(FontSizeBox.SelectedItem is double size){_appSettings.EditorFontSize=size;ApplyEditorPreferences();}}
 void RefreshAll(){RefreshTree();UpdateStatus();Title=$"{_document.Project.Title} — TagWriter";}
 void RefreshTree(){
  ProjectTree.Items.Clear(); var manuscript=new TreeViewItem{Header=MakeManuscriptHeader(_document.Chapters.Count==0),IsExpanded=true,Tag="manuscript",FontWeight=FontWeights.Bold,FontSize=15};
  foreach(var chapter in _document.Chapters.OrderBy(x=>x.Order)){var cn=new TreeViewItem{Header=MakeTreeHeader(chapter.Title,chapter,()=>AddSceneToChapter(chapter),chapter.Scenes.Count==0),IsExpanded=true,Tag=chapter,FontWeight=FontWeights.Normal,FontSize=13};foreach(var scene in chapter.Scenes.OrderBy(x=>x.Order))cn.Items.Add(new TreeViewItem{Header=MakeLeafTreeHeader(scene.Title,scene),Tag=scene,FontWeight=FontWeights.Normal,FontSize=13});manuscript.Items.Add(cn);} ProjectTree.Items.Add(manuscript);
  var cards=new TreeViewItem{Header="설정 카드",IsExpanded=true,FontWeight=FontWeights.Bold,FontSize=15}; foreach(CardType type in Enum.GetValues<CardType>()){var typeCards=_document.Cards.Where(x=>x.Type==type).OrderBy(x=>x.Name).ToList();var g=new TreeViewItem{Header=MakeCardCategoryHeader(type,typeCards.Count==0),IsExpanded=true,Tag=$"cardgroup:{type}",FontWeight=FontWeights.Normal,FontSize=13};foreach(var card in typeCards)g.Items.Add(new TreeViewItem{Header=MakeLeafTreeHeader(card.Name,card),Tag=card,FontWeight=FontWeights.Normal,FontSize=13});cards.Items.Add(g);} ProjectTree.Items.Add(cards);
  var ideasList=_document.Ideas.OrderBy(x=>x.CreatedAt).ToList();var ideas=new TreeViewItem{Header=MakeIdeaMemoHeader(ideasList.Count==0),IsExpanded=true,FontWeight=FontWeights.Bold,FontSize=15};foreach(var idea in ideasList)ideas.Items.Add(new TreeViewItem{Header=MakeLeafTreeHeader(idea.Title,idea),Tag=idea,FontWeight=FontWeights.Normal,FontSize=13});ProjectTree.Items.Add(ideas);
 }
 FrameworkElement MakeManuscriptHeader(bool emptyBranch){var grid=new Grid{HorizontalAlignment=HorizontalAlignment.Stretch};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var titlePanel=new StackPanel{Orientation=Orientation.Horizontal};if(emptyBranch)titlePanel.Children.Add(MakeTreeGlyph("◆"));titlePanel.Children.Add(new TextBlock{Text=_document.Project.Title,TextWrapping=TextWrapping.Wrap,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,8,0)});var add=new Button{Content="새 챕터",Padding=new Thickness(7,3,7,3),Margin=new Thickness(4,0,0,0),FontSize=11,FontWeight=FontWeights.Normal,VerticalAlignment=VerticalAlignment.Top,ToolTip="새 챕터 추가"};Grid.SetColumn(titlePanel,0);Grid.SetColumn(add,1);add.Click+=(_,e)=>{AddChapter();e.Handled=true;};grid.Children.Add(titlePanel);grid.Children.Add(add);return grid;}
 FrameworkElement MakeCardCategoryHeader(CardType type,bool emptyBranch){var panel=new StackPanel{Orientation=Orientation.Horizontal};if(emptyBranch)panel.Children.Add(MakeTreeGlyph("◆"));panel.Children.Add(new TextBlock{Text=TypeName(type),VerticalAlignment=VerticalAlignment.Center});if(!_treeEditMode){var add=new Button{Content="+",Width=22,Height=22,Padding=new Thickness(0),Margin=new Thickness(8,0,0,0),Background=Brushes.Transparent,BorderThickness=new Thickness(0),Foreground=(Brush)FindResource("Muted"),FontSize=16,FontWeight=FontWeights.Normal,Cursor=Cursors.Hand,ToolTip=$"{TypeName(type)} 카드 추가"};add.MouseEnter+=(_,_)=>{add.FontWeight=FontWeights.Bold;add.Foreground=(Brush)FindResource("Text");};add.MouseLeave+=(_,_)=>{add.FontWeight=FontWeights.Normal;add.Foreground=(Brush)FindResource("Muted");};add.Click+=(_,e)=>{CreateCard(type);e.Handled=true;};panel.Children.Add(add);}return panel;}
 FrameworkElement MakeIdeaMemoHeader(bool emptyBranch){var panel=new StackPanel{Orientation=Orientation.Horizontal};if(emptyBranch)panel.Children.Add(MakeTreeGlyph("◆"));panel.Children.Add(new TextBlock{Text="아이디어 메모",VerticalAlignment=VerticalAlignment.Center});if(!_treeEditMode){var add=new Button{Content="+",Width=22,Height=22,Padding=new Thickness(0),Margin=new Thickness(8,0,0,0),Background=Brushes.Transparent,BorderThickness=new Thickness(0),Foreground=(Brush)FindResource("Muted"),FontSize=16,FontWeight=FontWeights.Normal,Cursor=Cursors.Hand,ToolTip="아이디어 메모 추가"};add.MouseEnter+=(_,_)=>{add.FontWeight=FontWeights.Bold;add.Foreground=(Brush)FindResource("Text");};add.MouseLeave+=(_,_)=>{add.FontWeight=FontWeights.Normal;add.Foreground=(Brush)FindResource("Muted");};add.Click+=(_,e)=>{AddIdea_Click(add,new RoutedEventArgs());e.Handled=true;};panel.Children.Add(add);}return panel;}
 FrameworkElement MakeTreeHeader(string title,object item,Action? add,bool emptyBranch=false){var panel=new StackPanel{Orientation=Orientation.Horizontal};if(emptyBranch)panel.Children.Add(MakeTreeGlyph("◆"));if(_treeEditMode){var check=new CheckBox{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,6,0),IsChecked=_treeEditSelection.Contains(item)};check.Checked+=(_,_)=>_treeEditSelection.Add(item);check.Unchecked+=(_,_)=>_treeEditSelection.Remove(item);panel.Children.Add(check);}var label=new TextBlock{Text=title,VerticalAlignment=VerticalAlignment.Center};panel.Children.Add(label);if(!_treeEditMode&&add!=null){var plus=new Button{Content="+",Width=22,Height=22,Padding=new Thickness(0),Margin=new Thickness(8,0,0,0),Background=Brushes.Transparent,BorderThickness=new Thickness(0),Foreground=(Brush)FindResource("Muted"),FontSize=16,FontWeight=FontWeights.Normal,Cursor=Cursors.Hand,ToolTip="추가"};plus.MouseEnter+=(_,_)=>{plus.FontWeight=FontWeights.Bold;plus.Foreground=(Brush)FindResource("Text");};plus.MouseLeave+=(_,_)=>{plus.FontWeight=FontWeights.Normal;plus.Foreground=(Brush)FindResource("Muted");};plus.Click+=(_,e)=>{add!();e.Handled=true;};panel.Children.Add(plus);}return panel;}
 TextBlock MakeTreeGlyph(string glyph)=>new(){Text=glyph,Width=14,TextAlignment=TextAlignment.Center,Foreground=(Brush)FindResource("Muted"),VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(-16,0,2,0),FontWeight=FontWeights.Normal};
 FrameworkElement MakeLeafTreeHeader(string title,object item){var panel=new StackPanel{Orientation=Orientation.Horizontal};panel.Children.Add(MakeTreeGlyph("-"));if(_treeEditMode){var check=new CheckBox{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,6,0),IsChecked=_treeEditSelection.Contains(item)};check.Checked+=(_,_)=>_treeEditSelection.Add(item);check.Unchecked+=(_,_)=>_treeEditSelection.Remove(item);panel.Children.Add(check);}panel.Children.Add(new TextBlock{Text=title,VerticalAlignment=VerticalAlignment.Center});return panel;}
 void TreeEdit_Click(object s,RoutedEventArgs e){_treeEditMode=true;_treeEditSelection.Clear();TreeEditButton.Visibility=Visibility.Collapsed;TreeDeleteButton.Visibility=Visibility.Visible;TreeUndoButton.Visibility=Visibility.Visible;TreeEditDoneButton.Visibility=Visibility.Visible;RefreshTree();}
 void TreeEditDone_Click(object s,RoutedEventArgs e){_treeEditMode=false;_treeEditSelection.Clear();TreeEditButton.Visibility=Visibility.Visible;TreeDeleteButton.Visibility=Visibility.Collapsed;TreeUndoButton.Visibility=Visibility.Collapsed;TreeEditDoneButton.Visibility=Visibility.Collapsed;RefreshTree();}
 void TreeDelete_Click(object s,RoutedEventArgs e){
  var chapters=_treeEditSelection.OfType<Chapter>().ToList();
  var scenes=_treeEditSelection.OfType<Scene>().Where(sc=>!chapters.Any(ch=>ch.Scenes.Contains(sc))).ToList();
  var cards=_treeEditSelection.OfType<EntityCard>().ToList();
  var ideas=_treeEditSelection.OfType<Idea>().ToList();
  if(chapters.Count==0&&scenes.Count==0&&cards.Count==0&&ideas.Count==0)return;
  var count=chapters.Count+scenes.Count+cards.Count+ideas.Count;
  if(MessageBox.Show($"선택한 {count}개 항목을 삭제할까?","선택 삭제",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;
  PersistEditor();
  var snapCh=chapters.Select(ch=>(ch,_document.Chapters.IndexOf(ch))).ToList();
  var snapSc=scenes.Select(sc=>{var ch=_document.Chapters.First(x=>x.Scenes.Contains(sc));return(sc,ch,ch.Scenes.IndexOf(sc));}).ToList();
  var snapCards=cards.Select(card=>(card,_document.Cards.IndexOf(card))).ToList();
  var snapIdeas=ideas.Select(idea=>(idea,_document.Ideas.IndexOf(idea))).ToList();
  var deletedCardIds=cards.Select(card=>card.Id).ToHashSet();
  var snapNodes=_document.MindMap.Nodes.Where(n=>deletedCardIds.Contains(n.CardId)).ToList();
  var snapEdges=_document.MindMap.Edges.Where(edge=>deletedCardIds.Contains(edge.From)||deletedCardIds.Contains(edge.To)).ToList();
  var snapshot=new TreeDeleteSnapshot(snapCh,snapSc,snapCards,snapIdeas,snapNodes,snapEdges);
  _treeUndo.Push(()=>{
   foreach(var (ch,index) in snapshot.Chapters.OrderBy(x=>x.index))if(!_document.Chapters.Contains(ch))_document.Chapters.Insert(Math.Min(index,_document.Chapters.Count),ch);
   foreach(var (sc,ch,index) in snapshot.Scenes.OrderBy(x=>x.index))if(_document.Chapters.Contains(ch)&&!ch.Scenes.Contains(sc))ch.Scenes.Insert(Math.Min(index,ch.Scenes.Count),sc);
   foreach(var (card,index) in snapshot.Cards.OrderBy(x=>x.index))if(!_document.Cards.Contains(card))_document.Cards.Insert(Math.Min(index,_document.Cards.Count),card);
   foreach(var (idea,index) in snapshot.Ideas.OrderBy(x=>x.index))if(!_document.Ideas.Contains(idea))_document.Ideas.Insert(Math.Min(index,_document.Ideas.Count),idea);
   foreach(var node in snapshot.Nodes)if(!_document.MindMap.Nodes.Any(n=>n.CardId==node.CardId))_document.MindMap.Nodes.Add(node);
   foreach(var edge in snapshot.Edges)if(!_document.MindMap.Edges.Any(e=>e.Id==edge.Id))_document.MindMap.Edges.Add(edge);
   NormalizeTreeOrder();
  });
  foreach(var sc in scenes){var ch=_document.Chapters.FirstOrDefault(x=>x.Scenes.Contains(sc));ch?.Scenes.Remove(sc);if(_scene==sc)_scene=null;}
  foreach(var ch in chapters){if(_scene!=null&&ch.Scenes.Contains(_scene))_scene=null;_document.Chapters.Remove(ch);}
  foreach(var card in cards)_document.Cards.Remove(card);
  if(deletedCardIds.Count>0){_document.MindMap.Nodes.RemoveAll(n=>deletedCardIds.Contains(n.CardId));_document.MindMap.Edges.RemoveAll(edge=>deletedCardIds.Contains(edge.From)||deletedCardIds.Contains(edge.To));}
  foreach(var idea in ideas)_document.Ideas.Remove(idea);
  if(_card!=null&&cards.Contains(_card)){_card=null;CardName.Text="";CardTypeText.Text="";CardDetailHost.Children.Clear();CardEditHost.Children.Clear();OccurrenceHost.Children.Clear();ContextTabs.SelectedIndex=0;}
  if(_idea!=null&&ideas.Contains(_idea)){_idea=null;_ideaMemoContextVisible=false;IdeaMemoTitle.Text="아이디어 메모";IdeaMemoBody.Text="";if(!_rightCollapsed){IdeaMemoView.Visibility=Visibility.Collapsed;ContextTabs.Visibility=Visibility.Visible;}}
  NormalizeTreeOrder();_document.Project.UpdatedAt=DateTimeOffset.Now;_treeEditSelection.Clear();TreeUndoButton.IsEnabled=true;RefreshTree();if(_scene==null)SelectFirstScene();UpdateStatus();
 }
 void TreeUndo_Click(object s,RoutedEventArgs e){if(_treeUndo.Count==0)return;_treeUndo.Pop()();TreeUndoButton.IsEnabled=_treeUndo.Count>0;RefreshTree();UpdateStatus();}
 void NormalizeTreeOrder(){var chapters=_document.Chapters.OrderBy(x=>x.Order).ToList();_document.Chapters.Clear();foreach(var chapter in chapters){var scenes=chapter.Scenes.OrderBy(x=>x.Order).ToList();chapter.Scenes.Clear();chapter.Scenes.AddRange(scenes);_document.Chapters.Add(chapter);}NormalizeTreeOrderByList();}
 void NormalizeTreeOrderByList(){for(int i=0;i<_document.Chapters.Count;i++){_document.Chapters[i].Order=i+1;for(int j=0;j<_document.Chapters[i].Scenes.Count;j++)_document.Chapters[i].Scenes[j].Order=j+1;}}
 void AddChapter(){PersistEditor();var n=_document.Chapters.Count+1;var ch=new Chapter{Title=NextChapterTitle(n),Order=n};ch.Scenes.Add(new Scene{Title="Scene 1",Order=1});_document.Chapters.Add(ch);RefreshTree();ShowScene(ch.Scenes[0]);}
 void AddChapterAfter(Chapter chapter){PersistEditor();var ordered=_document.Chapters.OrderBy(x=>x.Order).ToList();var pos=ordered.IndexOf(chapter)+1;var ch=new Chapter{Title=NextChapterTitle(_document.Chapters.Count+1),Order=pos+1};ch.Scenes.Add(new Scene{Title="Scene 1",Order=1});_document.Chapters.Add(ch);for(int i=0;i<ordered.Count;i++)ordered[i].Order=i<pos?i+1:i+2;RefreshTree();ShowScene(ch.Scenes[0]);}
 void AddSceneToChapter(Chapter chapter){PersistEditor();var sc=new Scene{Title=$"Scene {chapter.Scenes.Count+1}",Order=chapter.Scenes.Count+1};chapter.Scenes.Add(sc);RefreshTree();ShowScene(sc);}
 void AddSceneAfter(Scene scene){var chapter=_document.Chapters.FirstOrDefault(x=>x.Scenes.Contains(scene));if(chapter==null)return;PersistEditor();var ordered=chapter.Scenes.OrderBy(x=>x.Order).ToList();var pos=ordered.IndexOf(scene)+1;var sc=new Scene{Title=$"Scene {chapter.Scenes.Count+1}",Order=pos+1};chapter.Scenes.Add(sc);for(int i=0;i<ordered.Count;i++)ordered[i].Order=i<pos?i+1:i+2;RefreshTree();ShowScene(sc);}
 static string TypeName(CardType t)=>t switch{CardType.Character=>"캐릭터",CardType.Location=>"장소",CardType.Item=>"물건",CardType.Event=>"이벤트",_=>t.ToString()};
 void SelectFirstScene(){var s=_document.Chapters.OrderBy(x=>x.Order).SelectMany(x=>x.Scenes.OrderBy(y=>y.Order)).FirstOrDefault();if(s!=null)ShowScene(s);}
 void ProjectTree_MouseDoubleClick(object s,System.Windows.Input.MouseButtonEventArgs e){if(ProjectTree.SelectedItem is not TreeViewItem i)return;if(i.Tag as string=="manuscript"){RenameProject();e.Handled=true;}else if(i.Tag is Chapter chapter){RenameChapter(chapter);e.Handled=true;}else if(i.Tag is Scene scene){RenameScene(scene);e.Handled=true;}}
 void RenameChapter(Chapter chapter){if(ShowRenameDialog("장 제목 변경",chapter.Title,out var title)){chapter.Title=title;_document.Project.UpdatedAt=DateTimeOffset.Now;RefreshTree();if(_scene!=null)ShowScene(_scene);}}
 void RenameScene(Scene scene){if(ShowRenameDialog("씬 이름 변경",scene.Title,out var title)){scene.Title=title;_document.Project.UpdatedAt=DateTimeOffset.Now;RefreshTree();ShowScene(scene);}}
 void ProjectTree_PreviewMouseLeftButtonDown(object s,MouseButtonEventArgs e){_treeDragStart=e.GetPosition(ProjectTree);_treeDragItem=FindTreeItem(e.OriginalSource as DependencyObject)?.Tag;}
 void ProjectTree_PreviewMouseMove(object s,MouseEventArgs e){if(!_treeEditMode||e.LeftButton!=MouseButtonState.Pressed||_treeDragItem is not (Scene or Chapter))return;var p=e.GetPosition(ProjectTree);if(Math.Abs(p.X-_treeDragStart.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(p.Y-_treeDragStart.Y)<SystemParameters.MinimumVerticalDragDistance)return;DragDrop.DoDragDrop(ProjectTree,_treeDragItem,DragDropEffects.Move);_treeDragItem=null;}
 void ProjectTree_DragOver(object s,DragEventArgs e){var item=FindTreeItem(e.OriginalSource as DependencyObject);var draggedScene=e.Data.GetData(typeof(Scene)) as Scene;var draggedChapter=e.Data.GetData(typeof(Chapter)) as Chapter;var valid=_treeEditMode&&item!=null&&((draggedScene!=null&&item.Tag is Scene or Chapter)||(draggedChapter!=null&&item.Tag is Chapter));e.Effects=valid?DragDropEffects.Move:DragDropEffects.None;if(valid&&item!=null){var p=e.GetPosition(item);ShowDropIndicator(item,p.Y>=item.ActualHeight/2);}else ClearDropIndicators();e.Handled=true;}
 void ProjectTree_DragLeave(object s,DragEventArgs e){if(!ProjectTree.IsMouseOver)ClearDropIndicators();}
 void ShowDropIndicator(TreeViewItem item,bool after){if(_dropIndicatorItem!=item){ClearDropIndicators();_dropIndicatorItem=item;}item.BorderBrush=(Brush)FindResource("Accent");item.BorderThickness=after?new Thickness(0,0,0,4):new Thickness(0,4,0,0);}
 void ProjectTree_Drop(object s,DragEventArgs e){if(!_treeEditMode)return;var item=FindTreeItem(e.OriginalSource as DependencyObject);var target=item?.Tag;var after=item!=null&&e.GetPosition(item).Y>=item.ActualHeight/2;ClearDropIndicators();if(e.Data.GetData(typeof(Scene)) is Scene scene)MoveScene(scene,target,after);else if(e.Data.GetData(typeof(Chapter)) is Chapter chapter)MoveChapter(chapter,target,after);e.Handled=true;}
 void ClearDropIndicators(){foreach(var root in ProjectTree.Items.OfType<TreeViewItem>())ClearDropIndicators(root);_dropIndicatorItem=null;}
 void ClearDropIndicators(TreeViewItem item){item.ClearValue(Control.BorderBrushProperty);item.ClearValue(Control.BorderThicknessProperty);item.ClearValue(Control.BackgroundProperty);foreach(var child in item.Items.OfType<TreeViewItem>())ClearDropIndicators(child);}
 TreeViewItem? FindTreeItem(DependencyObject? d){while(d!=null&&d is not TreeViewItem)d=VisualTreeHelper.GetParent(d);return d as TreeViewItem;}
 void MoveScene(Scene scene,object? target,bool after){var from=_document.Chapters.FirstOrDefault(x=>x.Scenes.Contains(scene));if(from==null||target==scene)return;Chapter? to=target as Chapter;if(target is Scene tsc)to=_document.Chapters.FirstOrDefault(x=>x.Scenes.Contains(tsc));if(to==null)return;var oldIndex=from.Scenes.IndexOf(scene);from.Scenes.Remove(scene);int insert;if(target is Scene targetScene){var targetIndex=to.Scenes.IndexOf(targetScene);insert=Math.Max(0,targetIndex+(after?1:0));}else insert=to.Scenes.Count;to.Scenes.Insert(Math.Min(insert,to.Scenes.Count),scene);NormalizeTreeOrderByList();_treeUndo.Push(()=>{to.Scenes.Remove(scene);from.Scenes.Insert(Math.Min(oldIndex,from.Scenes.Count),scene);NormalizeTreeOrderByList();});TreeUndoButton.IsEnabled=true;RefreshTree();}
 void MoveChapter(Chapter chapter,object? target,bool after){if(target is not Chapter tch||tch==chapter)return;var old=_document.Chapters.IndexOf(chapter);_document.Chapters.Remove(chapter);var index=_document.Chapters.IndexOf(tch)+(after?1:0);_document.Chapters.Insert(Math.Clamp(index,0,_document.Chapters.Count),chapter);NormalizeTreeOrderByList();_treeUndo.Push(()=>{_document.Chapters.Remove(chapter);_document.Chapters.Insert(Math.Min(old,_document.Chapters.Count),chapter);NormalizeTreeOrderByList();});TreeUndoButton.IsEnabled=true;RefreshTree();}

