 void AddDetailMemo(string memo){CardDetailHost.Children.Add(new TextBlock{Text="메모",FontWeight=FontWeights.SemiBold,FontSize=11,Margin=new Thickness(0,2,0,5)});var block=new TextBlock{TextWrapping=TextWrapping.Wrap,LineHeight=20,Margin=new Thickness(0,0,0,15)};AppendLinkedText(block,memo);CardDetailHost.Children.Add(block);}
 void AppendLinkedText(TextBlock block,string text){if(string.IsNullOrEmpty(text)){block.Text="";return;}var rx=new Regex(@"https?://[^\s]+",RegexOptions.IgnoreCase);var pos=0;foreach(Match m in rx.Matches(text)){if(m.Index>pos)block.Inlines.Add(new Run(text[pos..m.Index]));var url=m.Value;var link=new Hyperlink(new Run(url)){NavigateUri=new Uri(url)};link.Click+=(_,_)=>OpenExternalUrl(url);block.Inlines.Add(link);pos=m.Index+m.Length;}if(pos<text.Length)block.Inlines.Add(new Run(text[pos..]));}
