 void AddDetailTags(EntityCard c){CardDetailHost.Children.Add(new TextBlock{Text="태그",FontWeight=FontWeights.SemiBold,FontSize=11,Margin=new Thickness(0,0,0,6)});var wrap=new WrapPanel{Margin=new Thickness(0,0,0,16)};wrap.Children.Add(MakeTagBadge(c.Name+" · 기본",c.Type));foreach(var alias in c.Aliases)wrap.Children.Add(MakeTagBadge(alias,c.Type));CardDetailHost.Children.Add(wrap);}
