 void AddConnectedTags(EntityCard c){var edges=_document.MindMap.Edges.Where(e=>e.From==c.Id||e.To==c.Id).ToList();if(edges.Count==0)return;CardDetailHost.Children.Add(new Border{Height=1,Background=(Brush)FindResource("Border"),Margin=new Thickness(0,4,0,14)});CardDetailHost.Children.Add(new TextBlock{Text="연결된 태그",FontWeight=FontWeights.SemiBold,FontSize=11,Margin=new Thickness(0,0,0,7)});var wrap=new WrapPanel();foreach(var edge in edges){var id=edge.From==c.Id?edge.To:edge.From;var other=_document.Cards.FirstOrDefault(x=>x.Id==id);if(other==null)continue;var row=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,8,6)};var manual=!string.Equals(edge.Source,"auto",StringComparison.OrdinalIgnoreCase);var b=new Button{Content=other.Name,Background=Brushes.Transparent,BorderThickness=new Thickness(0),Padding=new Thickness(2),Foreground=manual?RelationshipBrush(edge.Source):CardTypeBrush(other.Type),Cursor=Cursors.Hand,ToolTip=manual?"수동 관계":"자동 관계"};b.Click+=(_,_)=>{ShowCard(other);SelectCardInTree(other);};row.Children.Add(b);wrap.Children.Add(row);}CardDetailHost.Children.Add(wrap);}
 Brush CardTypeBrush(CardType type){var hex=type switch{CardType.Character=>_dark?"#60A5FA":"#2563EB",CardType.Location=>_dark?"#F87171":"#DC2626",CardType.Event=>_dark?"#FBBF24":"#B45309",_=>_dark?"#E6E9ED":"#20242A"};return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex));}
