 string GetEditorText(){var text=NormalizeRichText(new TextRange(Editor.Document.ContentStart,Editor.Document.ContentEnd).Text);if(text.EndsWith("\n",StringComparison.Ordinal))text=text[..^1];return text;}
 void SetEditorText(string? text){Editor.Document.Blocks.Clear();var p=new Paragraph{Margin=new Thickness(0),LineHeight=Math.Max(Editor.FontSize*1.7,Editor.FontSize+6)};p.Inlines.Add(new Run(text??""));Editor.Document.Blocks.Add(p);Editor.Document.FontFamily=Editor.FontFamily;Editor.Document.FontSize=Editor.FontSize;Editor.Document.PagePadding=new Thickness(0);}
 int GetEditorCaretOffset(){var text=NormalizeRichText(new TextRange(Editor.Document.ContentStart,Editor.CaretPosition).Text);return Math.Min(text.Length,GetEditorText().Length);}


 static string NormalizeRichText(string text)=>text.Replace("\r\n","\n").Replace('\r','\n');
 TextPointer GetEditorPointerAtOffset(int offset)
 {
  var target=Math.Clamp(offset,0,GetEditorText().Length);
  var current=Editor.Document.ContentStart.GetInsertionPosition(LogicalDirection.Forward)??Editor.Document.ContentStart;
  var logical=NormalizeRichText(new TextRange(Editor.Document.ContentStart,current).Text).Length;
  if(target<=logical)return current;

  while(current.CompareTo(Editor.Document.ContentEnd)<0)
  {
   var next=current.GetNextInsertionPosition(LogicalDirection.Forward);
   if(next==null)break;

   var segment=NormalizeRichText(new TextRange(current,next).Text);
   var nextLogical=logical+segment.Length;

   if(target<=nextLogical)return next;

   logical=nextLogical;
   current=next;
  }

  return Editor.Document.ContentEnd.GetInsertionPosition(LogicalDirection.Backward)??Editor.Document.ContentEnd;
 }
 int GetEditorOffsetFromPointer(TextPointer position){var text=NormalizeRichText(new TextRange(Editor.Document.ContentStart,position).Text);return Math.Min(text.Length,GetEditorText().Length);}
 void Editor_TextChanged(object s,TextChangedEventArgs e){if(_loading||_formattingTags||_scene==null)return;_scene.Content=GetEditorText();MarkSceneRelationshipDirty(_scene);UpdateStatus();if(_card!=null)RefreshOccurrences(_card);ScheduleTagFormatting();}
 void ScheduleTagFormatting(){if(_paperMode||_scene==null||_tagFormatTimer==null)return;_tagFormatTimer.Stop();_tagFormatTimer.Start();}
 static bool IsSentenceTerminator(char ch)=>ch=='.'||ch=='?'||ch=='!'||ch=='…';
 static List<(int Start,int Length)> GetCompletedSentenceSpans(string text){
  var spans=new List<(int Start,int Length)>();var start=0;
  for(var i=0;i<text.Length;i++){
   if(!IsSentenceTerminator(text[i]))continue;
   var end=i+1;while(end<text.Length&&IsSentenceTerminator(text[end]))end++;
   if(end>start)spans.Add((start,end-start));start=end;i=end-1;
  }
  return spans;
 }
 static bool IsInsideCompletedSentence(int start,int length,List<(int Start,int Length)> spans)=>spans.Any(s=>start>=s.Start&&start+length<=s.Start+s.Length);
 List<TagHit> FindTagHits(string text){
  var completed=GetCompletedSentenceSpans(text);var candidates=new List<TagHit>();
  foreach(var card in _document.Cards.Where(c=>c.Type is CardType.Character or CardType.Location)){
   foreach(var term in card.Aliases.Append(card.Name).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.CurrentCultureIgnoreCase)){
    var from=0;while(from<text.Length){var at=text.IndexOf(term,from,StringComparison.CurrentCultureIgnoreCase);if(at<0)break;if(IsInsideCompletedSentence(at,term.Length,completed))candidates.Add(new TagHit(at,term.Length,card));from=at+Math.Max(1,term.Length);}
   }
  }
  var hits=new List<TagHit>();foreach(var hit in candidates.OrderBy(x=>x.Start).ThenByDescending(x=>x.Length)){if(hits.Any(x=>hit.Start<x.Start+x.Length&&x.Start<hit.Start+hit.Length))continue;hits.Add(hit);}return hits;
 }
 void ApplyEditorTagFormatting(){
  if(_paperMode||_scene==null||_loading)return;_formattingTags=true;
  try{
   _editorTagSpans.Clear();var all=new TextRange(Editor.Document.ContentStart,Editor.Document.ContentEnd);all.ApplyPropertyValue(TextElement.ForegroundProperty,(Brush)FindResource("Text"));all.ApplyPropertyValue(TextElement.FontWeightProperty,FontWeights.Normal);all.ApplyPropertyValue(Inline.TextDecorationsProperty,null);all.ApplyPropertyValue(TextElement.BackgroundProperty,Brushes.Transparent);
   var text=GetEditorText();foreach(var hit in FindTagHits(text)){var start=GetEditorPointerAtOffset(hit.Start);var end=GetEditorPointerAtOffset(hit.Start+hit.Length);var range=new TextRange(start,end);var fg=InlineTagBrush(hit.Card.Type);range.ApplyPropertyValue(TextElement.ForegroundProperty,fg);range.ApplyPropertyValue(TextElement.FontWeightProperty,FontWeights.SemiBold);range.ApplyPropertyValue(Inline.TextDecorationsProperty,TextDecorations.Underline);if(fg is SolidColorBrush sb)range.ApplyPropertyValue(TextElement.BackgroundProperty,new SolidColorBrush(Color.FromArgb(_dark?(byte)10:(byte)7,sb.Color.R,sb.Color.G,sb.Color.B)));_editorTagSpans.Add(new EditorTagSpan(hit.Start,hit.Length,hit.Card.Id));}
  }finally{_formattingTags=false;}
 }
 void Editor_PreviewMouseLeftButtonUp(object s,MouseButtonEventArgs e){if(_paperMode||_scene==null)return;var pointer=Editor.GetPositionFromPoint(e.GetPosition(Editor),true);if(pointer==null)return;var offset=GetEditorOffsetFromPointer(pointer);var span=_editorTagSpans.FirstOrDefault(x=>offset>=x.Start&&offset<x.Start+x.Length);if(span==null)return;var card=_document.Cards.FirstOrDefault(c=>c.Id==span.CardId);if(card==null)return;ShowCard(card);SelectCardInTree(card);e.Handled=true;}
 void Editor_PreviewMouseMove(object s,MouseEventArgs e){if(_paperMode||_scene==null){Editor.Cursor=Cursors.IBeam;return;}var pointer=Editor.GetPositionFromPoint(e.GetPosition(Editor),true);if(pointer==null){Editor.Cursor=Cursors.IBeam;return;}var offset=GetEditorOffsetFromPointer(pointer);Editor.Cursor=_editorTagSpans.Any(x=>offset>=x.Start&&offset<x.Start+x.Length)?Cursors.Hand:Cursors.IBeam;}
 void RefreshOccurrencesForScene(){if(_card!=null)RefreshOccurrences(_card);else OccurrenceHost.Children.Clear();}
 void RefreshOccurrences(EntityCard c){
  OccurrenceHost.Children.Clear();if(c.Type is not (CardType.Character or CardType.Location)){OccurrenceHost.Children.Add(new TextBlock{Text=c.Type==CardType.Event?"이벤트 카드는 원고 자동 태그/등장 검색 대상이 아닙니다.":"이 카드 유형의 자동 태그 동작은 아직 정해지지 않았습니다.",Foreground=(Brush)FindResource("Muted"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(4)});return;}
  var hits=FindOccurrences(c);if(hits.Count==0){OccurrenceHost.Children.Add(new TextBlock{Text="원고에서 아직 발견되지 않았습니다.",Foreground=(Brush)FindResource("Muted"),Margin=new Thickness(4)});return;}
  foreach(var hit in hits){var panel=new StackPanel();var head=new Grid();head.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});head.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var where=new TextBlock{Text=$"{hit.Chapter.Title} | {hit.Scene.Title} | {hit.LineNumber}줄",Foreground=(Brush)FindResource("Muted"),FontSize=11,VerticalAlignment=VerticalAlignment.Center};var go=new Button{Content="이동",Padding=new Thickness(7,2,7,2),FontSize=10,IsEnabled=!_paperMode,ToolTip=_paperMode?"원고지 모드에서는 위치 이동을 사용하지 않습니다.":"해당 위치로 이동"};go.Click+=(_,_)=>NavigateToOccurrence(c,hit);Grid.SetColumn(go,1);head.Children.Add(where);head.Children.Add(go);panel.Children.Add(head);panel.Children.Add(new TextBlock{Text=hit.LineText,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,0),LineHeight=19});OccurrenceHost.Children.Add(new Border{BorderBrush=(Brush)FindResource("Border"),BorderThickness=new Thickness(0,0,0,1),Padding=new Thickness(4,7,4,9),Child=panel});}
 }
 List<OccurrenceHit> FindOccurrences(EntityCard c){
  var hits=new List<OccurrenceHit>();
  foreach(var ch in _document.Chapters.OrderBy(x=>x.Order))foreach(var sc in ch.Scenes.OrderBy(x=>x.Order)){
   var text=sc.Content??"";foreach(var m in FindTagHits(text).Where(x=>x.Card.Id==c.Id)){
    var lineStart=text.LastIndexOf('\n',Math.Max(0,m.Start-1));lineStart=lineStart<0?0:lineStart+1;var lineEnd=text.IndexOf('\n',m.Start);if(lineEnd<0)lineEnd=text.Length;var lineNo=1+text.Take(m.Start).Count(x=>x=='\n');hits.Add(new OccurrenceHit(ch,sc,m.Start,m.Length,lineNo,text[lineStart..lineEnd].TrimEnd('\r')));
   }
  }
  return hits.OrderBy(h=>h.Chapter.Order).ThenBy(h=>h.Scene.Order).ThenBy(h=>h.Offset).ToList();
 }
 void NavigateToOccurrence(EntityCard card,OccurrenceHit hit){if(_paperMode)return;ShowScene(hit.Scene);_card=card;RefreshOccurrences(card);ContextTabs.SelectedIndex=0;var text=GetEditorText();var offset=Math.Clamp(hit.Offset,0,text.Length);var start=GetEditorPointerAtOffset(offset);var end=GetEditorPointerAtOffset(Math.Min(text.Length,offset+hit.Length));Editor.Focus();Editor.Selection.Select(start,end);Editor.CaretPosition=end;start.Paragraph?.BringIntoView();}
