 public async Task<bool> LoadProjectFromPathAsync(string path){
  try{_document=await ProjectStore.LoadAsync(path);_path=path;_scene=null;_card=null;_idea=null;RefreshAll();InitializeTypingSoundPreferences();InitializeRelationshipSnapshots();SelectFirstScene();_lastAutoSaveAt=DateTimeOffset.Now;RememberRecentProject(path);return true;}
  catch(Exception ex){MessageBox.Show(ex.Message,"열기 실패");return false;}
 }
 void RememberRecentProject(string path){
  if(string.IsNullOrWhiteSpace(path))return;
  string normalized;
  try{normalized=System.IO.Path.GetFullPath(path);}catch{normalized=path;}
  _appSettings.RecentProjectPath=normalized;
  _appSettings.RecentProjectPaths??=[];
  _appSettings.RecentProjectPaths.RemoveAll(p=>string.Equals(p,normalized,StringComparison.OrdinalIgnoreCase));
  _appSettings.RecentProjectPaths.Add(normalized);
  AppSettingsStore.Save(_appSettings);
 }
 void SaveCommand_Executed(object s,ExecutedRoutedEventArgs e)=>SaveProject_Click(s,e);
 async void SaveProject_Click(object s,RoutedEventArgs e)=>await SaveProjectCoreAsync(false);
 async Task<bool> SaveProjectCoreAsync(bool automatic){
  if(_saveInProgress)return false;
  if(_path==null){
   if(automatic)return false;
   var d=new SaveFileDialog{Filter="TagWriter JSON (*.json)|*.json",FileName=(string.IsNullOrWhiteSpace(_document.Project.Title)?"novel":_document.Project.Title)+".json"};if(d.ShowDialog()!=true)return false;_path=d.FileName;
  }
  PersistEditor();if(!automatic)FinalizeRelationshipScenes(_document.Chapters.SelectMany(c=>c.Scenes).Select(sc=>sc.Id));
  try{_saveInProgress=true;await ProjectStore.SaveAsync(_path,_document);RememberRecentProject(_path);_lastAutoSaveAt=DateTimeOffset.Now;UpdateStatus(automatic?$"자동 저장됨 {DateTime.Now:HH:mm}":"저장됨");return true;}
  catch(Exception ex){if(automatic)UpdateStatus("자동 저장 실패");else MessageBox.Show(ex.Message,"저장 실패");return false;}
  finally{_saveInProgress=false;}
 }
 void InitializeAutoSavePreferences(){
  var allowed=new[]{1,3,5,10};if(!allowed.Contains(_appSettings.AutoSaveMinutes))_appSettings.AutoSaveMinutes=10;
  if(AutoSaveIntervalComboBox!=null){foreach(var item in AutoSaveIntervalComboBox.Items.OfType<ComboBoxItem>())if(int.TryParse(item.Tag?.ToString(),out var n)&&n==_appSettings.AutoSaveMinutes){AutoSaveIntervalComboBox.SelectedItem=item;break;}}
  _lastAutoSaveAt=DateTimeOffset.Now;
 }
 void AutoSaveIntervalComboBox_SelectionChanged(object s,SelectionChangedEventArgs e){
  if(AutoSaveIntervalComboBox.SelectedItem is not ComboBoxItem item||!int.TryParse(item.Tag?.ToString(),out var minutes))return;
  _appSettings.AutoSaveMinutes=minutes;_lastAutoSaveAt=DateTimeOffset.Now;if(IsLoaded)AppSettingsStore.Save(_appSettings);
 }
 async void AutoSaveTimer_Tick(object? s,EventArgs e){
  if(_path==null||_saveInProgress)return;var minutes=Math.Clamp(_appSettings.AutoSaveMinutes,1,10);if(DateTimeOffset.Now-_lastAutoSaveAt<TimeSpan.FromMinutes(minutes))return;await SaveProjectCoreAsync(true);
 }
 void MarkSceneRelationshipDirty(Scene scene){_pendingRelationshipSceneIds.Add(scene.Id);_pendingSceneFinalizeAt.Remove(scene.Id);_lastEditorInputAt=DateTimeOffset.Now;}
 void RelationshipIdleTimer_Tick(object? s,EventArgs e){
  var now=DateTimeOffset.Now;var due=new HashSet<string>();
  foreach(var p in _pendingSceneFinalizeAt)if(now-p.Value>=TimeSpan.FromSeconds(10)&&_pendingRelationshipSceneIds.Contains(p.Key))due.Add(p.Key);
  if(_scene!=null&&_pendingRelationshipSceneIds.Contains(_scene.Id)&&now-_lastEditorInputAt>=TimeSpan.FromSeconds(10))due.Add(_scene.Id);
  if(due.Count>0)FinalizeRelationshipScenes(due);
 }
 void InitializeRelationshipSnapshots(){
  _sceneAutoPairs.Clear();foreach(var sc in _document.Chapters.SelectMany(c=>c.Scenes))_sceneAutoPairs[sc.Id]=BuildSceneAutoPairs(sc);RebuildAutoEdgesFromSnapshots();
  _pendingRelationshipSceneIds.Clear();_pendingSceneFinalizeAt.Clear();
 }
 Dictionary<(string A,string B),int> BuildSceneAutoPairs(Scene scene){
  var result=new Dictionary<(string A,string B),int>();var text=scene.Content??"";var hits=FindTagHits(text);var completed=GetCompletedSentenceSpans(text);
  foreach(var span in completed){
   var ids=hits.Where(h=>h.Start>=span.Start&&h.Start<span.Start+span.Length).Select(h=>h.Card.Id).Distinct().OrderBy(x=>x,StringComparer.Ordinal).ToArray();
   for(var i=0;i<ids.Length;i++)for(var j=i+1;j<ids.Length;j++){var key=(ids[i],ids[j]);result[key]=result.TryGetValue(key,out var count)?count+1:1;}
  }
  return result;
 }
 void FinalizeRelationshipScenes(IEnumerable<string> sceneIds){
  var ids=sceneIds.Distinct().ToArray();if(ids.Length==0)return;var scenes=_document.Chapters.SelectMany(c=>c.Scenes).ToDictionary(sc=>sc.Id);
  foreach(var id in ids){if(scenes.TryGetValue(id,out var sc))_sceneAutoPairs[id]=BuildSceneAutoPairs(sc);else _sceneAutoPairs.Remove(id);_pendingRelationshipSceneIds.Remove(id);_pendingSceneFinalizeAt.Remove(id);}
  RebuildAutoEdgesFromSnapshots();
 }
 void RebuildAutoEdgesFromSnapshots(){
  var validScenes=_document.Chapters.SelectMany(c=>c.Scenes).Select(sc=>sc.Id).ToHashSet();foreach(var stale in _sceneAutoPairs.Keys.Where(id=>!validScenes.Contains(id)).ToList())_sceneAutoPairs.Remove(stale);
  var validCards=_document.Cards.Select(c=>c.Id).ToHashSet();var totals=new Dictionary<(string A,string B),int>();
  foreach(var pairs in _sceneAutoPairs.Values)foreach(var p in pairs){if(!validCards.Contains(p.Key.A)||!validCards.Contains(p.Key.B))continue;totals[p.Key]=totals.TryGetValue(p.Key,out var count)?count+p.Value:p.Value;}
  _document.MindMap.Edges.RemoveAll(e=>string.Equals(e.Source,"auto",StringComparison.OrdinalIgnoreCase));
  foreach(var p in totals)_document.MindMap.Edges.Add(new MapEdge{From=p.Key.A,To=p.Key.B,Source="auto",Strength=p.Value});
  if(MindMapView.Visibility==Visibility.Visible)DrawMindMap();if(_card!=null&&CardDetailHost.Visibility==Visibility.Visible)BuildCardDetail(_card);
 }
 string NextChapterTitle(int n){var first=_document.Chapters.OrderBy(x=>x.Order).FirstOrDefault()?.Title??"";return first.StartsWith("Chapter ",StringComparison.OrdinalIgnoreCase)?$"Chapter {n}":$"{n}장";}
 void AddChapter_Click(object s,RoutedEventArgs e)=>AddChapter();
 void AddScene_Click(object s,RoutedEventArgs e){var ch=_document.Chapters.FirstOrDefault(x=>x.Scenes.Contains(_scene!))??_document.Chapters.LastOrDefault();if(ch!=null)AddSceneToChapter(ch);}
 void AddCard_Click(object s,RoutedEventArgs e){if(s is not MenuItem i||!Enum.TryParse<CardType>(i.Tag?.ToString(),out var t))return;CreateCard(t);}
 void CreateCard(CardType type){
  if(type==CardType.Item){MessageBox.Show("물건 카드는 세부 항목과 자동 태그 동작이 아직 확정되지 않았습니다. 항목을 정한 뒤 구현합니다.","물건 카드");return;}
  if(!ShowCardCreateDialog(type,out var card)||card==null)return;
  _document.Cards.Add(card);_document.MindMap.Nodes.Add(new MapNode{CardId=card.Id,Placed=false,UserPositioned=false});_document.Project.UpdatedAt=DateTimeOffset.Now;
  RefreshTree();ShowCard(card);SelectCardInTree(card);foreach(var sc in _document.Chapters.SelectMany(c=>c.Scenes))_pendingRelationshipSceneIds.Add(sc.Id);_lastEditorInputAt=DateTimeOffset.Now;ScheduleTagFormatting();UpdateStatus($"{TypeName(type)} 카드 추가됨");
 }
 bool ShowCardCreateDialog(CardType type,out EntityCard? result){
  result=null;var dlg=new Window{Title=$"{TypeName(type)} 카드 추가",Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Width=520,Height=type==CardType.Character?720:540,MinHeight=420,ResizeMode=ResizeMode.CanResize,Background=(Brush)FindResource("Panel"),Foreground=(Brush)FindResource("Text")};
  var root=new DockPanel{Margin=new Thickness(18)};var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};var cancel=new Button{Content="취소",MinWidth=72,Padding=new Thickness(10,5,10,5),Margin=new Thickness(0,0,6,0),IsCancel=true};var ok=new Button{Content="저장",MinWidth=72,Padding=new Thickness(10,5,10,5),IsDefault=true};buttons.Children.Add(cancel);buttons.Children.Add(ok);DockPanel.SetDock(buttons,Dock.Bottom);root.Children.Add(buttons);
  var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};var form=new StackPanel{Margin=new Thickness(0,0,8,0)};scroll.Content=form;root.Children.Add(scroll);dlg.Content=root;dlg.SourceInitialized+=(_,_)=>ApplyWindowChromeTheme(dlg);
  var fields=new Dictionary<string,TextBox>();TextBox Add(string key,string label,string value="",bool multi=false,bool readOnly=false){form.Children.Add(new TextBlock{Text=label,FontSize=11,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,5)});var box=new TextBox{Text=value,Padding=new Thickness(8,6,8,6),Margin=new Thickness(0,0,0,12),AcceptsReturn=multi,TextWrapping=multi?TextWrapping.Wrap:TextWrapping.NoWrap,VerticalScrollBarVisibility=multi?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled,Height=multi?110:double.NaN,IsReadOnly=readOnly};form.Children.Add(box);fields[key]=box;return box;}
  var name=Add("name","이름");
  if(type==CardType.Character){var age=Add("age","나이");var birthday=Add("birthday","생일 (MM-DD)");var refDate=Add("ref","나이 기준일 (YYYY-MM-DD)");var birthYear=Add("birthyear","출생년 (자동 계산)","",false,true);Add("family","가족");Add("education","학력");Add("memo","메모","",true);Add("tags","태그 · 추가 별칭 (, 로 구분)");void Recalc(object? _,TextChangedEventArgs __){birthYear.Text=CalculateBirthYear(age.Text,birthday.Text,refDate.Text)?.ToString()??"";}age.TextChanged+=Recalc;birthday.TextChanged+=Recalc;refDate.TextChanged+=Recalc;}
  else {Add("memo","메모","",true);Add("tags","태그 · 추가 별칭 (, 로 구분)");}
  EntityCard? accepted=null;ok.Click+=(_,_)=>{var n=name.Text.Trim();if(n.Length==0){MessageBox.Show("이름을 입력해 주세요.","카드 추가");return;}var c=new EntityCard{Type=type,Name=n,Memo=fields["memo"].Text,Aliases=ParseAliases(fields["tags"].Text),UpdatedAt=DateTimeOffset.Now};if(type==CardType.Character){c.Age=int.TryParse(fields["age"].Text.Trim(),out var ageValue)?ageValue:null;c.Birthday=fields["birthday"].Text.Trim();c.AgeReferenceDate=fields["ref"].Text.Trim();c.BirthYear=CalculateBirthYear(fields["age"].Text,c.Birthday,c.AgeReferenceDate);c.Family=fields["family"].Text.Trim();c.Education=fields["education"].Text.Trim();}accepted=c;dlg.DialogResult=true;};
  dlg.Loaded+=(_,_)=>name.Focus();if(dlg.ShowDialog()!=true||accepted==null)return false;result=accepted;return true;
 }
 static int? CalculateBirthYear(string ageText,string birthday,string referenceDate){if(!int.TryParse(ageText.Trim(),out var age)||age<0||!DateTime.TryParse(referenceDate,out var reference))return null;var parts=birthday.Trim().Replace('/','-').Replace('.','-').Split('-',StringSplitOptions.RemoveEmptyEntries);if(parts.Length!=2||!int.TryParse(parts[0],out var month)||!int.TryParse(parts[1],out var day)||month<1||month>12||day<1||day>31)return null;var year=reference.Year-age;if(reference.Month<month||(reference.Month==month&&reference.Day<day))year--;return year;}
 static List<string> ParseAliases(string text)=>text.Split([',','\r','\n'],StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Where(x=>x.Length>0).Distinct(StringComparer.CurrentCultureIgnoreCase).ToList();
 void CardEditButton_Click(object s,RoutedEventArgs e){if(_card==null)return;if(_card.Type==CardType.Item){MessageBox.Show("물건 카드의 세부 항목은 아직 확정되지 않았습니다.","물건 카드");return;}BuildCardEditor(_card);}
 void BuildCardEditor(EntityCard card){
  _cardEditFields.Clear();CardDetailHost.Visibility=Visibility.Collapsed;CardEditButton.Visibility=Visibility.Collapsed;CardEditHost.Visibility=Visibility.Visible;CardEditHost.Children.Clear();
  TextBox Add(string key,string label,string value="",bool multi=false,bool readOnly=false){CardEditHost.Children.Add(new TextBlock{Text=label,FontSize=11,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,5)});var box=new TextBox{Text=value,Padding=new Thickness(8,6,8,6),Margin=new Thickness(0,0,0,12),AcceptsReturn=multi,TextWrapping=multi?TextWrapping.Wrap:TextWrapping.NoWrap,VerticalScrollBarVisibility=multi?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled,Height=multi?110:double.NaN,IsReadOnly=readOnly};CardEditHost.Children.Add(box);_cardEditFields[key]=box;return box;}
  var name=Add("name","이름",card.Name);
  if(card.Type==CardType.Character){var age=Add("age","나이",card.Age?.ToString()??"");var birthday=Add("birthday","생일 (MM-DD)",card.Birthday);var refDate=Add("ref","나이 기준일 (YYYY-MM-DD)",card.AgeReferenceDate);var birthYear=Add("birthyear","출생년 (자동 계산)",card.BirthYear?.ToString()??"",false,true);Add("family","가족",card.Family);Add("education","학력",card.Education);Add("memo","메모",card.Memo,true);Add("tags","태그 · 추가 별칭 (, 로 구분)",string.Join(", ",card.Aliases));void Recalc(object? _,TextChangedEventArgs __){birthYear.Text=CalculateBirthYear(age.Text,birthday.Text,refDate.Text)?.ToString()??"";}age.TextChanged+=Recalc;birthday.TextChanged+=Recalc;refDate.TextChanged+=Recalc;}
  else {Add("memo","메모",card.Memo,true);Add("tags","태그 · 추가 별칭 (, 로 구분)",string.Join(", ",card.Aliases));}
  var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,4,0,0)};var cancel=new Button{Content="취소",Padding=new Thickness(10,5,10,5),Margin=new Thickness(0,0,6,0)};var save=new Button{Content="저장",Padding=new Thickness(10,5,10,5)};cancel.Click+=(_,_)=>ExitCardEdit(false);save.Click+=(_,_)=>ExitCardEdit(true);buttons.Children.Add(cancel);buttons.Children.Add(save);CardEditHost.Children.Add(buttons);name.Focus();name.SelectAll();
 }
 void ExitCardEdit(bool save){
  if(_card==null)return;
  if(save){var name=_cardEditFields["name"].Text.Trim();if(name.Length==0){MessageBox.Show("이름을 입력해 주세요.","카드 수정");return;}_card.Name=name;_card.Memo=_cardEditFields["memo"].Text;_card.Aliases=ParseAliases(_cardEditFields["tags"].Text);if(_card.Type==CardType.Character){_card.Age=int.TryParse(_cardEditFields["age"].Text.Trim(),out var age)?age:null;_card.Birthday=_cardEditFields["birthday"].Text.Trim();_card.AgeReferenceDate=_cardEditFields["ref"].Text.Trim();_card.BirthYear=CalculateBirthYear(_cardEditFields["age"].Text,_card.Birthday,_card.AgeReferenceDate);_card.Family=_cardEditFields["family"].Text.Trim();_card.Education=_cardEditFields["education"].Text.Trim();}_card.UpdatedAt=DateTimeOffset.Now;_document.Project.UpdatedAt=DateTimeOffset.Now;RefreshTree();SelectCardInTree(_card);foreach(var sc in _document.Chapters.SelectMany(c=>c.Scenes))_pendingRelationshipSceneIds.Add(sc.Id);_lastEditorInputAt=DateTimeOffset.Now;}
