 void ShowAll_Click(object s,RoutedEventArgs e){_relationshipAnchorCardId=null;SetActivityButton(ProjectModeButton);PersistEditor();if(_scene!=null)_lastScene=_scene;_scene=null;_loading=true;BuildFullManuscriptDocument();Editor.Visibility=Visibility.Collapsed;ManuscriptPaperScroll.Visibility=Visibility.Collapsed;FullManuscriptReader.Visibility=Visibility.Visible;UpdateEditorPaperBackgroundVisibility();EditorTitle.Text="전체 원고";EditorSubtitle.Text="연속 읽기 · 읽기 전용";_loading=false;EditorView.Visibility=Visibility.Visible;MindMapView.Visibility=Visibility.Collapsed;}
 void BuildFullManuscriptDocument(){var doc=new FlowDocument{PagePadding=new Thickness(0),FontFamily=Editor.FontFamily,FontSize=Editor.FontSize,Foreground=(Brush)FindResource("Text")};var title=new Paragraph(new Run(_document.Project.Title)){TextAlignment=TextAlignment.Center,FontSize=Editor.FontSize+4,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,34)};doc.Blocks.Add(title);var chapters=_document.Chapters.OrderBy(x=>x.Order).ToList();for(int i=0;i<chapters.Count;i++){var ch=chapters[i];doc.Blocks.Add(new Paragraph(new Run(ch.Title)){TextAlignment=TextAlignment.Left,FontSize=Editor.FontSize+1,Margin=new Thickness(0,0,0,18)});foreach(var sc in ch.Scenes.OrderBy(x=>x.Order)){if(!string.IsNullOrEmpty(sc.Content))doc.Blocks.Add(new Paragraph(new Run(sc.Content)){TextAlignment=TextAlignment.Left,LineHeight=Math.Max(Editor.FontSize*1.7,Editor.FontSize+6),Margin=new Thickness(0,0,0,8)});}if(i<chapters.Count-1){doc.Blocks.Add(new Paragraph(new Run("────────────────────────")){TextAlignment=TextAlignment.Left,Foreground=(Brush)FindResource("Muted"),Margin=new Thickness(0,42,0,42)});}}FullManuscriptReader.Document=doc;FullManuscriptReader.ScrollToHome();}
