 void PaperMode_Click(object s,RoutedEventArgs e){PersistEditor();_paperMode=true;_appSettings.PaperMode=true;UpdateEditorPaperBackgroundVisibility();_loading=true;var text=GetEditorText();var caret=GetEditorCaretOffset();PaperInput.Text=text;PaperInput.CaretIndex=Math.Min(caret,PaperInput.Text.Length);_loading=false;_editorTagSpans.Clear();Editor.Visibility=Visibility.Collapsed;PaperInput.Visibility=Visibility.Visible;ManuscriptPaperScroll.Visibility=Visibility.Visible;PaperZoomControls.Visibility=Visibility.Visible;NormalTextControls.Visibility=Visibility.Collapsed;if(_card!=null)RefreshOccurrences(_card);RenderManuscriptPaper();PaperInput.Focus();}
 void SyncPaperToEditor(){if(!_paperMode)return;_loading=true;SetEditorText(PaperInput.Text);if(_scene!=null)_scene.Content=PaperInput.Text;_loading=false;UpdateStatus();RefreshOccurrencesForScene();}
 void PaperInput_TextChanged(object s,TextChangedEventArgs e){if(_loading||!_paperMode)return;if(_scene!=null){_scene.Content=PaperInput.Text;MarkSceneRelationshipDirty(_scene);}SchedulePaperRender();UpdateStatus();RefreshOccurrencesForScene();}
 void SchedulePaperRender(){if(_paperRenderTimer==null){RenderManuscriptPaper();return;}_paperRenderTimer.Stop();_paperRenderTimer.Start();}
 void PaperInput_SelectionChanged(object s,RoutedEventArgs e){if(_paperMode)SchedulePaperRender();}
 void PaperInput_PreviewKeyDown(object s,KeyEventArgs e){PlayTypingKey(e);if(!_paperMode||(e.Key!=Key.Up&&e.Key!=Key.Down)){if((Keyboard.Modifiers&ModifierKeys.Shift)==0)_paperKeyboardSelectionAnchor=null;return;}var text=PaperInput.Text??"";var shift=(Keyboard.Modifiers&ModifierKeys.Shift)!=0;var current=PaperInput.CaretIndex;if(shift){_paperKeyboardSelectionAnchor??=PaperInput.SelectionLength==0?current:(current<=PaperInput.SelectionStart?PaperInput.SelectionStart+PaperInput.SelectionLength:PaperInput.SelectionStart);if(PaperInput.SelectionLength>0){var start=PaperInput.SelectionStart;var end=start+PaperInput.SelectionLength;current=_paperKeyboardSelectionAnchor==start?end:start;}}else _paperKeyboardSelectionAnchor=null;var currentDisplay=PaperDisplayIndexFromTextIndex(text,current);var targetDisplay=Math.Max(0,currentDisplay+(e.Key==Key.Down?20:-20));var target=TextIndexFromPaperDisplayIndex(text,targetDisplay);if(shift){var anchor=_paperKeyboardSelectionAnchor!.Value;SetPaperSelection(anchor,target);}else PaperInput.Select(target,0);e.Handled=true;SchedulePaperRender();}
 void PaperZoomOut_Click(object s,RoutedEventArgs e)=>SetPaperZoom(_paperZoom-.1);
