 void SetPaperZoom(double value){_paperFit=false;_paperZoom=Math.Clamp(value,.35,2.5);_appSettings.PaperFit=false;_appSettings.PaperZoom=_paperZoom;RenderManuscriptPaper();}
 void PaperFit_Click(object s,RoutedEventArgs e){_paperFit=true;_appSettings.PaperFit=true;RenderManuscriptPaper();}
 void ManuscriptPaperScroll_SizeChanged(object s,SizeChangedEventArgs e){if(_paperMode&&_paperFit)RenderManuscriptPaper();}
 void ManuscriptPaperScroll_PreviewMouseWheel(object s,MouseWheelEventArgs e){if(!_paperMode)return;if((Keyboard.Modifiers&ModifierKeys.Control)!=0){SetPaperZoom(_paperZoom+(e.Delta>0?.1:-.1));e.Handled=true;return;}if((Keyboard.Modifiers&ModifierKeys.Shift)!=0){ManuscriptPaperScroll.ScrollToHorizontalOffset(ManuscriptPaperScroll.HorizontalOffset-(e.Delta/3.0));e.Handled=true;}}
 int PaperDisplayIndexFromTextIndex(string text,int textIndex){const int cols=20;var lineStart=0;var lineChars=0;for(int i=0;i<Math.Min(textIndex,text.Length);i++){var ch=text[i];if(ch=='\r')continue;if(ch=='\n'){var rows=Math.Max(1,(lineChars+cols-1)/cols);lineStart+=rows*cols;lineChars=0;}else lineChars++;}return lineStart+lineChars;}
 int TextIndexFromPaperDisplayIndex(string text,int displayIndex){var bestIndex=0;var bestDistance=int.MaxValue;for(int i=0;i<=text.Length;i++){var p=PaperDisplayIndexFromTextIndex(text,i);var d=Math.Abs(p-displayIndex);if(d<bestDistance||(d==bestDistance&&p<=displayIndex)){bestDistance=d;bestIndex=i;}if(p>displayIndex&&d>bestDistance)break;}return bestIndex;}
 char[] BuildPaperDisplay(string text,out int usedCells){const int cols=20;var placed=new Dictionary<int,char>();var lineStart=0;var lineChars=0;foreach(var ch in text){if(ch=='\r')continue;if(ch=='\n'){var rows=Math.Max(1,(lineChars+cols-1)/cols);lineStart+=rows*cols;lineChars=0;continue;}placed[lineStart+lineChars]=ch;lineChars++;}usedCells=Math.Max(lineStart+lineChars,1);var result=Enumerable.Repeat('\0',usedCells).ToArray();foreach(var kv in placed)if(kv.Key<result.Length)result[kv.Key]=kv.Value;return result;}
 void PaperSurface_MouseDown(ManuscriptPaperSurface surface,int displayIndex,MouseButtonEventArgs e){var textIndex=TextIndexFromPaperDisplayIndex(PaperInput.Text,displayIndex);_paperDragging=true;_paperDragAnchorText=textIndex;ManuscriptPaperScroll.CaptureMouse();if((Keyboard.Modifiers&ModifierKeys.Shift)!=0){var anchor=PaperInput.SelectionLength>0?PaperInput.SelectionStart:PaperInput.CaretIndex;SetPaperSelection(anchor,textIndex);}else{PaperInput.Select(textIndex,0);_paperDragAnchorText=textIndex;}PaperInput.Focus();UpdatePaperSurfaceStates();}
 void PaperSurface_MouseMove(ManuscriptPaperSurface surface,int displayIndex,MouseEventArgs e){if(!_paperDragging)return;var textIndex=TextIndexFromPaperDisplayIndex(PaperInput.Text,displayIndex);SetPaperSelection(_paperDragAnchorText,textIndex);UpdatePaperSurfaceStates();}
 void PaperSurface_MouseUp(ManuscriptPaperSurface surface,MouseButtonEventArgs e){_paperDragging=false;PaperInput.Focus();}
 void ManuscriptPaperScroll_PreviewMouseMove(object s,MouseEventArgs e){if(!_paperDragging||e.LeftButton!=MouseButtonState.Pressed)return;var p=e.GetPosition(ManuscriptPaperScroll);const double edge=48;if(p.Y<edge)ManuscriptPaperScroll.ScrollToVerticalOffset(Math.Max(0,ManuscriptPaperScroll.VerticalOffset-22));else if(p.Y>ManuscriptPaperScroll.ViewportHeight-edge)ManuscriptPaperScroll.ScrollToVerticalOffset(ManuscriptPaperScroll.VerticalOffset+22);var bestCell=-1;var bestDistance=double.MaxValue;foreach(var surface in _paperSurfaces){var q=e.GetPosition(surface);var col=(int)Math.Floor((q.X/_paperZoom-PaperMargin)/PaperCell);var row=(int)Math.Floor((q.Y/_paperZoom-PaperMargin)/PaperCell);if(col>=0&&col<20&&row>=0&&row<10){bestCell=surface.PageIndex*200+row*20+col;break;}var clampedX=Math.Clamp(q.X,PaperMargin*_paperZoom,(PaperMargin+20*PaperCell)*_paperZoom-1);var clampedY=Math.Clamp(q.Y,PaperMargin*_paperZoom,(PaperMargin+10*PaperCell)*_paperZoom-1);var dx=q.X-clampedX;var dy=q.Y-clampedY;var d=dx*dx+dy*dy;if(d<bestDistance){bestDistance=d;col=Math.Clamp((int)((clampedX/_paperZoom-PaperMargin)/PaperCell),0,19);row=Math.Clamp((int)((clampedY/_paperZoom-PaperMargin)/PaperCell),0,9);bestCell=surface.PageIndex*200+row*20+col;}}if(bestCell>=0){var textIndex=TextIndexFromPaperDisplayIndex(PaperInput.Text,bestCell);SetPaperSelection(_paperDragAnchorText,textIndex);UpdatePaperSurfaceStates();}e.Handled=true;}
 void ManuscriptPaperScroll_PreviewMouseLeftButtonUp(object s,MouseButtonEventArgs e){if(!_paperDragging)return;_paperDragging=false;if(ManuscriptPaperScroll.IsMouseCaptured)ManuscriptPaperScroll.ReleaseMouseCapture();PaperInput.Focus();e.Handled=true;}
 void SetPaperSelection(int anchor,int current){var start=Math.Min(anchor,current);var length=Math.Abs(current-anchor);PaperInput.Select(start,length);}
 void EnsurePaperSurfaceCount(int pages,double logicalW,double logicalH){while(_paperSurfaces.Count<pages){var surface=new ManuscriptPaperSurface();surface.CellMouseDown+=PaperSurface_MouseDown;surface.CellMouseMove+=PaperSurface_MouseMove;surface.CellMouseUp+=PaperSurface_MouseUp;_paperSurfaces.Add(surface);ManuscriptPaperHost.Children.Add(surface);}while(_paperSurfaces.Count>pages){var last=_paperSurfaces[^1];ManuscriptPaperHost.Children.Remove(last);_paperSurfaces.RemoveAt(_paperSurfaces.Count-1);}for(int p=0;p<pages;p++){var s=_paperSurfaces[p];s.PageIndex=p;s.Zoom=_paperZoom;s.CellSize=PaperCell;s.PaperMargin=PaperMargin;s.Width=logicalW*_paperZoom;s.Height=logicalH*_paperZoom;s.Margin=new Thickness(0,0,0,22);s.PaperBrush=(Brush)FindResource("Panel2");s.GridBrush=(Brush)FindResource("Border");s.TextBrush=(Brush)FindResource("Text");s.CaretBrush=(Brush)FindResource("Selection");s.SelectionBrush=(Brush)FindResource("Selection");s.HoverBrush=(Brush)FindResource("Accent");s.PageNumberBrush=(Brush)FindResource("Muted");}}
 void UpdatePaperSurfaceStates(){var text=PaperInput.Text??"";var caret=PaperDisplayIndexFromTextIndex(text,PaperInput.CaretIndex);var selStart=PaperDisplayIndexFromTextIndex(text,PaperInput.SelectionStart);var selEnd=PaperDisplayIndexFromTextIndex(text,PaperInput.SelectionStart+PaperInput.SelectionLength);foreach(var s in _paperSurfaces){s.CaretCell=PaperInput.SelectionLength==0?caret:-1;s.SelectionStartCell=PaperInput.SelectionLength>0?Math.Min(selStart,selEnd):-1;s.SelectionEndCell=PaperInput.SelectionLength>0?Math.Max(selStart,selEnd):-1;s.InvalidateVisual();}}
 void EnsureCaretVisible(){if(_paperSurfaces.Count==0)return;var cell=PaperDisplayIndexFromTextIndex(PaperInput.Text,PaperInput.CaretIndex);var page=Math.Clamp(cell/200,0,_paperSurfaces.Count-1);_paperSurfaces[page].BringIntoView();}
 void RenderManuscriptPaper(){if(!_paperMode)return;var text=PaperInput.Text??"";var chars=BuildPaperDisplay(text,out var usedCells);const int perPage=200,cols=20,rows=10;var caretDisplay=PaperDisplayIndexFromTextIndex(text,PaperInput.CaretIndex);var pages=Math.Max(1,(int)Math.Ceiling(Math.Max(usedCells,caretDisplay+1)/(double)perPage));var logicalW=cols*PaperCell+PaperMargin*2;var logicalH=rows*PaperCell+PaperMargin*2;if(_paperFit&&ManuscriptPaperScroll.ViewportWidth>100)_paperZoom=Math.Clamp((ManuscriptPaperScroll.ViewportWidth-72)/logicalW,.35,1.6);PaperZoomText.Text=$"{_paperZoom*100:0}%";PaperPageText.Text=$"{pages}매 · 20×10";EnsurePaperSurfaceCount(pages,logicalW,logicalH);for(int p=0;p<pages;p++){var pageCells=new char[perPage];var from=p*perPage;var count=Math.Max(0,Math.Min(perPage,chars.Length-from));if(count>0)Array.Copy(chars,from,pageCells,0,count);_paperSurfaces[p].Cells=pageCells;}_document.Project.UpdatedAt=DateTimeOffset.Now;UpdatePaperSurfaceStates();EnsureCaretVisible();}
