 void ApplyTheme(bool dark){
  _dark=dark;
  SetBrush("Bg",dark?"#181B1F":"#E8EBEF"); SetBrush("Surface",dark?"#20242A":"#F5F6F8");
  SetBrush("Panel",dark?"#242930":"#EEF1F4"); SetBrush("Panel2",dark?"#2B3139":"#FFFFFF");
  SetBrush("EditorBg",dark?"#1D2126":"#FFFFFF"); SetBrush("Text",dark?"#E6E9ED":"#20242A");
  SetBrush("Muted",dark?"#939BA6":"#66707C"); SetBrush("Border",dark?"#343B45":"#D4D9E0");
  SetBrush("Accent",dark?"#70A9E8":"#2F72B7"); SetBrush("Selection",dark?"#304B68":"#BFD9F4"); SetBrush("Hover",dark?"#2B3139":"#E1E5EA"); SetBrush("ToolTipBg",dark?"#242930":"#FFFFFF"); SetBrush("ToolTipText",dark?"#E6E9ED":"#20242A"); SetBrush("TabSelected",dark?"#1E2227":"#E1E5EA");
  ThemeGlyph.Text=dark?"☾ Dark":"☀ Light"; ThemeGlyph.Foreground=(Brush)FindResource("Text"); ThemeToggle.Foreground=(Brush)FindResource("Text"); ThemeToggle.Background=(Brush)FindResource("Panel2"); ThemeToggle.IsChecked=!dark; _appSettings.Theme=dark?"dark":"light"; if(_activeActivityButton!=null)SetActivityButton(_activeActivityButton); if(_card!=null){CardTypeText.Foreground=CardTypeBrush(_card.Type);BuildCardDetail(_card);} if(!_paperMode)ApplyEditorTagFormatting(); if(MindMapView.Visibility==Visibility.Visible)DrawMindMap(); ApplyEditorPaperStyle(); ApplyWindowChromeTheme();
 }
